  /// Guards the assumption stated on [org.apache.pinot.core.auth.FineGrainedAuthUtils#getDeclaredQueryParams]: a
  /// table target's parameter must be bound as a `@PathParam` or a method-level `@QueryParam`. An endpoint binding it
  /// via `@BeanParam` or field injection would resolve no table and hard-fail with 400 for every caller, admin
  /// included. Cluster endpoints opting into table scope must also bind their `tableScopeParam`, otherwise a typo
  /// would silently retain cluster-wide scope and deny table-scoped callers.
  @Test
  public void testAuthorizeTableParamsAreBoundOnTheMethod()
      throws Exception {
    List<Class<?>> resourceClasses = controllerResourceClasses();
    assertTrue(resourceClasses.size() > 20, "expected to discover the controller resource classes, found "
        + resourceClasses.size());
    List<String> violations = new ArrayList<>();
    for (Class<?> resourceClass : resourceClasses) {
      for (Method method : resourceClass.getDeclaredMethods()) {
        Authorize authorize = method.getAnnotation(Authorize.class);
        if (authorize == null) {
          continue;
        }
        String parameterName;
        if (authorize.targetType() == TargetType.TABLE) {
          parameterName = authorize.paramName();
        } else if (authorize.targetType() == TargetType.CLUSTER && !authorize.tableScopeParam().isEmpty()) {
          parameterName = authorize.tableScopeParam();
        } else {
          continue;
        }
        if (!bindsParameter(method, parameterName)) {
          violations.add(resourceClass.getSimpleName() + "#" + method.getName() + " declares table parameter '"
              + parameterName + "'");
        }
      }
    }
    assertTrue(violations.isEmpty(), "@Authorize table parameters must be bound as @PathParam or @QueryParam: "
        + violations);
  }

  /// Loads every class in the controller's `api.resources` package from the compiled output, so the guard covers
  /// endpoints added later without anyone having to remember to list them here.
  private static List<Class<?>> controllerResourceClasses()
      throws Exception {
    String packageName = PinotTableRestletResource.class.getPackageName();
    // Resolve through URI so a build path containing spaces or other escaped characters still works.
    Path classesRoot = Path.of(
        PinotTableRestletResource.class.getProtectionDomain().getCodeSource().getLocation().toURI());
    Path packageRoot = classesRoot.resolve(packageName.replace('.', '/'));
    List<Class<?>> classes = new ArrayList<>();
    // Walked recursively so sub-packages such as api.resources.ddl are covered as they are added.
    try (Stream<Path> paths = Files.walk(packageRoot)) {
      for (Path classFile : paths.filter(Files::isRegularFile).toList()) {
        String fileName = classFile.getFileName().toString();
        if (!fileName.endsWith(".class") || fileName.contains("$")) {
          continue;
        }
        String relative = classesRoot.relativize(classFile).toString();
        String className = relative.substring(0, relative.length() - ".class".length())
            .replace(File.separatorChar, '.');
        try {
          classes.add(Class.forName(className));
        } catch (ClassNotFoundException | NoClassDefFoundError e) {
          // Not loadable in the test classpath; it cannot serve requests either.
        }
      }
    }
    return classes;
  }

  private static boolean bindsParameter(Method method, String parameterName) {
    for (Annotation[] parameterAnnotations : method.getParameterAnnotations()) {
      for (Annotation annotation : parameterAnnotations) {
        if (annotation instanceof PathParam pathParam && pathParam.value().equals(parameterName)) {
          return true;
        }
        if (annotation instanceof QueryParam queryParam && queryParam.value().equals(parameterName)) {
          return true;
        }
      }
    }
    return false;
  }

