  @Test
  public void testUserPasswordInUrl()
      throws Exception {
    Properties props = getBaseProperties();
    String urlWithCreds = getJdbcUrl() + "?user=UrlUser&password=UrlPass";

    try (Connection conn = DriverManager.getConnection(urlWithCreds, props)) {
